                  {win.app === 'overview' && <><span className="os-floating-eyebrow">СИСТЕМА · ДЕНЬ {day}</span><h3>{gameMinutes < 12 * 60 ? 'Доброе утро' : gameMinutes < 18 * 60 ? 'Хорошего дня' : 'Добрый вечер'}</h3><div className="os-floating-stat-grid"><div><small>ЕДИНЫЙ КАПИТАЛ</small><strong>{cash.toLocaleString('ru-RU')} ₽</strong></div><div><small>РЕПУТАЦИЯ</small><strong>{reputation}/100</strong></div></div><button className="os-floating-primary" onClick={() => { setTab('overview'); setWindowMinimized(false); setAppWindows((items) => items.map((item) => item.id === win.id ? { ...item, minimized: true } : item)) }}>Открыть полный обзор</button></>}
