                  {win.app === 'news' && <><span className="os-floating-eyebrow">ИНФОРМАЦИОННАЯ ЛЕНТА</span><h3>Новости рынка</h3><p>«Котолёт» открыл продажи новой очереди жилого квартала. Новость может повлиять на ожидания клиентов.</p><p>Перед сделкой сравни новость с отчётом компании и оцени риск.</p><button className="os-floating-primary" onClick={() => { setTab('news'); setAppWindows((items) => items.map((item) => item.id === win.id ? { ...item, minimized: true } : item)) }}>Открыть все новости</button></>}
